        Drifter drifter = new Drifter();
        Thread sleeper = new Thread(() -> drifter.tryToSleep());
        sleeper.start();

        // Simulate waking up after some time
        Thread.sleep(5000); // Sleep for 5 seconds
        drifter.asleep = true; // Wake the traveler

        sleeper.join(); // Wait for the sleeper thread to finish
    }
}

