import java.util.*;
import java.util.concurrent.*;

class CatIdentifier implements Comparable<CatIdentifier> {
    private final String identifier;

    public CatIdentifier(String identifier) {
        this.identifier = Objects.requireNonNull(identifier);
    }

    @Override
    public int compareTo(CatIdentifier other) {
        return this.identifier.compareTo(other.identifier);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof CatIdentifier)) return false;
        final CatIdentifier that = (CatIdentifier) obj;
        return Objects.equals(identifier, that.identifier);
    }

    @Override
    public int hashCode() {
        return identifier.hashCode();
    }

    @Override
    public String toString() {
        return identifier;
    }
}

class CosmicCats {
    private final Set<CatIdentifier> catIdentifiers;
    private static final ExecutorService executor = Executors.newFixedThreadPool(3);

    public CosmicCats(List<String> identifiers) {
        this.catIdentifiers = new HashSet<>(identifiers.size());
        identifiers.forEach(i -> executor.submit(() -> catIdentifiers.add(new CatIdentifier(i))));
        executor.shutdown();
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                throw new RuntimeException("Executor did not terminate");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
    }

    public boolean containsIdentifier(String identifier) {
        return catIdentifiers.contains(new CatIdentifier(identifier));
    }

    public String getAllCatIdentifiers() {
        List<CatIdentifier> sortedIdentifiers = new ArrayList<>(catIdentifiers);
        sortedIdentifiers.sort(Comparator.naturalOrder());
        return sortedIdentifiers.stream().map(Objects::toString).collect(Collectors.joining(", "));
    }
}

public class Main {
