        Map<String, Position> staticPositions = new HashMap<>(positions.size());
        for (Map.Entry<String, Position> entry : positions.entrySet()) {
            staticPositions.put(entry.getKey(), entry.getValue());
        }
        return Collections.unmodifiableMap(staticPositions);
    }

