import java.util.*;
import java.util.concurrent.*;

public class DelegatingParcelTracker {

    private final ConcurrentHashMap<String, String> packagePositions;

    public DelegatingParcelTracker(Map<String, String> initialPositions) {
        this.packagePositions = new ConcurrentHashMap<>(initialPositions);
    }

    public Optional<String> getPackagePosition(String packageId) {
        return Optional.ofNullable(packagePositions.get(packageId));
    }

    public boolean assignPackagePosition(String packageId, String position) {
        if (!packagePositions.containsKey(packageId)) {
            return false;
        }
        packagePositions.putIfAbsent(packageId, position);
        return true;
    }

    public Map<String, String> getLivePackagePositions() {
        return Collections.unmodifiableMap(packagePositions);
    }

    public Map<String, String> getSnapshotPackagePositions() {
        Map<String, String> snapshot = new HashMap<>(packagePositions.size());
        for (Map.Entry<String, String> entry : packagePositions.entrySet()) {
            snapshot.put(entry.getKey(), entry.getValue());
        }
        return Collections.unmodifiableMap(snapshot);
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, String> initialPositions = new HashMap<>();
        initialPositions.put("123456", "New York");
        initialPositions.put("654321", "Los Angeles");

        DelegatingParcelTracker tracker = new DelegatingParcelTracker(initialPositions);

        // Assign a package position from another thread
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<?> future = executor.submit(() -> {
            tracker.assignPackagePosition("123456", "Chicago");
        });

        // Retrieve positions concurrently from the main thread and another thread
        String newYorkPos = tracker.getPackagePosition("123456").orElseThrow(NoSuchElementException::new);
        System.out.println("New York position: " + newYorkPos);

        future.get(); // Wait for the assignment to complete

