import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.stream.Collectors;

public class DelegatingRobotTracker {

  private ConcurrentHashMap<String, Robot> robotMap = new ConcurrentHashMap<>();
  private ExecutorService executorService = Executors.newFixedThreadPool(3);

  public DelegatingRobotTracker(Map<String, Robot> initialRobots) {
    this.robotMap.putAll(initialRobots);
  }

  public void moveRobot(String robotId, int x, int y) {
    if (robotMap.containsKey(robotId)) {
      executorService.submit(() -> {
        Robot robot = robotMap.get(robotId);
        synchronized (robot) {
          int oldX = robot.getX();
          int oldY = robot.getY();
          robot.setCoordinates(x, y);
        }
      });
    } else {
      throw new IllegalArgumentException("Robot ID not found");
    }
  }

  public Robot getRobot(String robotId) {
    return robotMap.getOrDefault(robotId, null);
  }

  public Map<String, Robot> getAllRobots() {
    return Collections.unmodifiableMap(robotMap);
  }

  public Map<String, Robot> getAllRobotsSnapshot() {
    return robotMap.entrySet().stream()
        .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
  }

  private static class Robot {
    private int x;
    private int y;

    public Robot(int x, int y) {
      this.x = x;
      this.y = y;
    }

    public int getX() {
      return x;
    }

    public int getY() {
      return y;
    }

    public void setCoordinates(int x, int y) {
      this.x = x;
      this.y = y;
    }
  }

  public static void main(String[] args) {
    Map<String, Robot> initialRobots = new HashMap<>();
    initialRobots.put("robot1", new Robot(0, 0));
    initialRobots.put("robot2", new Robot(3, 4));

    DelegatingRobotTracker tracker = new DelegatingRobotTracker(initialRobots);

    // Check initial robot positions
    System.out.println(tracker.getRobot("robot1")); // Should print (0, 0)
    System.out.println(tracker.getRobot("robot2")); // Should print (3, 4)

    // Move a robot and check new positions
    tracker.moveRobot("robot1", 5, 6);
    System.out.println(tracker.getRobot("robot1")); // Should print (5, 6)

    // Attempt to move a non-existent robot
    try {
      tracker.moveRobot("nonexistent", 7, 8);
    } catch (IllegalArgumentException e) {
      System.out.println(e.getMessage()); // Should print "Robot ID not found"
    }

    // Get all robots as an unmodifiable map
    Map<String, Robot> allRobots = tracker.getAllRobots();
    System.out.println(AllRobots); // Should print {robot1=(5, 6), robot2=(3, 4)}

    // Get a snapshot of the current state as an unmodifiable map
    Map<String, Robot> AllRobotsSnapshot = tracker.getAllRobotsSnapshot();
    System.out.println(AllRobotsSnapshot); // Should print {robot1=(5, 6), robot2=(3, 4)}

    // Shut down the executor service
    executorService.shutdown();
  }
}

