import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ParcelMovement {
    private static final long FIXED_DELAY = 1000;
    private static final double RANDOM_DELAY = 500;

    static class ParcelCount {
        private int count;

        ParcelCount(int count) {
            this.count = count;
        }

        public synchronized void decrease(int amount) {
            if (amount > count) {
                throw new NotEnoughItemsException();
            }
            count -= amount;
        }
    }

    static class Locker {
        private final ReentrantLock lock = new ReentrantLock();
        private ParcelCount items;

        Locker(ParcelCount items) {
            this.items = items;
        }

        public boolean moveTo(Locker destination, int amount, long timeout, TimeUnit timeUnit) throws InterruptedException {
            if (lock.tryLock(timeout, timeUnit)) {
                try {
                    if (!destination.lock.tryLock(timeout, timeUnit)) {
                        Thread.sleep(calculateRandomDelay());
                        return destination.moveTo(this, amount, timeout, timeUnit);
                    }

                    try {
                        items.decrease(amount);
                        destination.items.count += amount;
                        return true;
                    } finally {
                        destination.lock.unlock();
                    }
                } finally {
                    lock.unlock();
                }
            } else {
                Thread.sleep(calculateRandomDelay());
                return moveTo(destination, amount, timeout, timeUnit);
            }
        }

        private long calculateFixedDelay() {
            return FIXED_DELAY;
        }

        private double calculateRandomDelay() {
            return (long) (Math.random() * RANDOM_DELAY);
        }
    }

    static class NotEnoughItemsException extends Exception {}

    public static void main(String[] args) throws InterruptedException {
        ParcelCount sourceItems = new ParcelCount(100);
        ParcelCount destinationItems = new ParcelCount(0);

        Locker sourceLocker = new Locker(sourceItems);
        Locker destinationLocker = new Locker(destinationItems);

        Thread thread1 = new Thread(() -> {
            try {
                if (sourceLocker.moveTo(destinationLocker, 50, 5000, TimeUnit.MILLISECONDS)) {
                    System.out.println("Parcel moved successfully");
                } else {
                    System.out.println("Failed to move parcel");
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                e.printStackTrace();
            }
        });

        thread1.start();
        thread1.join();
    }
}

import java.util.concurrent.*;

public class ParcelMover {
    static class NotEnoughItemsException extends Exception {
        NotEnoughItemsException(String message) { super(message); }
    }

    static class Locker<T> {
        private final T items;
        Locker(T items) { this.items = items; }
        synchronized boolean moveTo(Locker<T> target, int quantity, long timeoutMs, TimeUnit timeUnit) {
            long startTime = System.nanoTime();
            while (true) {
                if (System.nanoTime() - startTime > timeUnit.toNanos(timeoutMs)) return false;
                try {
                    Thread.sleep((long)(Math.random() * 1000)); // random pause before retrying lock acquisition
                } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                if (this.items >= quantity && this.tryLock()) {
                    try {
                        if (!target.tryLock(timeoutMs, timeUnit)) return false;
                        synchronized (target) {
                            int movedQuantity = Math.min(quantity, items);
                            items -= movedQuantity;
                            target.addItems(movedQuantity);
                        }
                    } catch (InterruptedException e) { Thread.currentThread().interrupt(); } finally {
                        this.unlock();
                        target.unlock();
                    }
                    return true;
                }
            }
        }
        synchronized void addItems(int quantity) { items += quantity; }
    }

    static class ParcelCount<T> {
        private final int quantity;
        ParcelCount(int quantity) { this.quantity = quantity; }
        int getQuantity() { return quantity; }
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Locker<Integer> source = new Locker<>(10);
        Locker<Integer> target = new Locker<>(0);

        Future<?> future1 = executor.submit(() -> {
            try { source.moveTo(target, 5, 5000, TimeUnit.MILLISECONDS); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        Future<?> future2 = executor.submit(() -> {
            try { target.moveTo(source, 3, 3000, TimeUnit.MILLISECONDS); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        future1.get();
        future2.get();

        executor.shutdownNow();
    }
}

import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class Parcel {
    public static void main(String[] args) throws InterruptedException {
        Locker source = new Locker("Source");
        Locker target = new Locker("Target");

        ParcelCount count = new ParcelCount();
        source.addParcels(count);
        target.removeParcels(count);

        Runnable moveTask = () -> {
            try {
                int quantity = new Random().nextInt(5) + 1;
                if (!move(source, target, count, 2, TimeUnit.SECONDS)) {
                    System.out.println("Failed to move " + quantity + " parcels from source to target.");
                } else {
                    System.out.println("Successfully moved " + quantity + " parcels from source to target.");
                }
            } catch (NotEnoughItemsException e) {
                System.out.println(e.getMessage());
            }
        };

        Thread thread1 = new Thread(moveTask);
        Thread thread2 = new Thread(moveTask);
        thread1.start();
        thread2.start();
        thread1.join();
        thread2.join();
    }

    public static boolean move(Locker source, Locker target, ParcelCount count, long timeoutDuration, TimeUnit timeUnit) throws NotEnoughItemsException {
        boolean acquiredSource = false;
        boolean acquiredTarget = false;

        while (!acquiredSource || !acquiredTarget) {
            if (!acquiredSource && source.lockerLock.tryLock(getRandomDelay(500, 1000), TimeUnit.MILLISECONDS)) {
                acquiredSource = true;
            }

            if (source.lockerLock.isHeldByCurrentThread()) {
                if (!target.lockerLock.tryLock(getRandomDelay(500, 1000), TimeUnit.MILLISECONDS)) {
                    source.lockerLock.unlock();
                    source.lockerLock.lock();
                    acquiredSource = false;
                } else {
                    acquiredTarget = true;
                }
            }

            if (acquiredSource && acquiredTarget) {
                if (!source.hasEnoughItems(count, new Random().nextInt(5) + 1)) {
                    throw new NotEnoughItemsException("Not enough items in source locker.");
                } else {
                    target.addParcels(count);
                    return true;
                }
            }

            if (source.lockerLock.isHeldByCurrentThread()) {
                source.lockerLock.unlock();
            }

            if (!acquiredSource && !acquiredTarget) {
                if (timeoutDuration > 0) {
                    return false;
                } else {
                    move(source, target, count, timeoutDuration - 1, timeUnit);
                }
            }

            timeUnit.sleep(getFixedDelay());
        }

        throw new RuntimeException("Unreachable code reached.");
    }

    private static long getRandomDelay(long min, long max) {
        return new Random().nextLong() % (max - min + 1) + min;
    }

    private static long getFixedDelay() {
        return new Random().nextLong() % 10;
    }
}

class ParcelCount {
    private int value = 0;

    public synchronized void addParcels(int count) {
        value += count;
    }

    public synchronized boolean hasEnoughItems(int quantity, int toRemove) {
        return value >= quantity + toRemove;
    }

    public synchronized void removeParcels(int count) {
        value -= count;
    }
}

class Locker {
    private String name;
    private ReentrantLock lockerLock = new ReentrantLock();

    public Locker(String name) {
        this.name = name;
    }

    public synchronized void addParcels(ParcelCount count) {
        count.addParcels(1);
    }

    public synchronized boolean hasEnoughItems(ParcelCount count, int quantityToRemove) {
        return count.hasEnoughItems(quantityToRemove, 0);
    }

    public synchronized void removeParcels(ParcelCount count) {
        count.removeParcels(1);
    }
}

