import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class ContainerSwapper {

    static class ElementCount<T> {
        private T element;
        private int count;

        ElementCount(T element, int count) {
            this.element = element;
            this.count = count;
        }

        public T getElement() {
            return element;
        }

        public int getCount() {
            return count;
        }

        void incrementCount() {
            ++count;
        }

        void decrementCount() {
            --count;
        }
    }

    static class Container<T> {
        private ElementCount<T>[] elements;

        Container(ElementCount<T>[] elements) {
            this.elements = elements;
        }

        public ElementCount<T>[] getElements() {
            return elements;
        }

        void swapElements(int originIndex, int targetIndex) {
            ElementCount<T> originElement = elements[originIndex];
            ElementCount<T> targetElement = elements[targetIndex];

            if (originElement.getCount() < 1) throw new InsufficientElementsException();

            originElement.decrementCount();
            targetElement.incrementCount();
        }
    }

    static class SwapTask implements Runnable {
        private final Container<String> originContainer;
        private final Container<String> targetContainer;
        private int numberOfElementsToSwap;
        private long timeoutDuration;
        private TimeUnit timeUnit;

        public SwapTask(Container<String> originContainer, Container<String> targetContainer, int numberOfElementsToSwap, long timeoutDuration, TimeUnit timeUnit) {
            this.originContainer = originContainer;
            this.targetContainer = targetContainer;
            this.numberOfElementsToSwap = numberOfElementsToSwap;
            this.timeoutDuration = timeoutDuration;
            this.timeUnit = timeUnit;
        }

        @Override
        public void run() {
            ReentrantLock originLock = new ReentrantLock();
            ReentrantLock targetLock = new ReentrantLock();

            while (true) {
                try {
                    if (!originLock.tryLock(calculateRandomWaitTime(), TimeUnit.MILLISECONDS)) continue;
                    if (!targetLock.tryLock(calculateRandomWaitTime(), TimeUnit.MILLISECONDS)) {
                        originLock.unlock();
                        continue;
                    }

                    int originIndex = (int) Math.random() * originContainer.getElements().length;
                    int targetIndex = (int) Math.random() * targetContainer.getElements().length;

                    if (!originContainer.getElements()[originIndex].getElement().equals(targetContainer.getElements()[targetIndex].getElement())) continue;

                    boolean swapped = false;
                    for (int i = 0; i < numberOfElementsToSwap && !swapped; ++i) {
                        if (!originContainer.getElements()[originIndex].getElement().equals(targetContainer.getElements()[targetIndex].getElement())) continue;

                        try {
                            originContainer.swapElements(originIndex, targetIndex);
                            swapped = true;
                        } catch (InsufficientElementsException e) {
                        }
                    }

                    if (!swapped) continue;
                } finally {
                    targetLock.unlock();
                    originLock.unlock();
                }

                return;
            }
        }

