import java.util.concurrent.Executors;
import java.util.concurrent.locks.ReentrantLock;

public class DeadlockAvoider {
    private ExecutorService executor = Executors.newFixedThreadPool(3);
    private Random random = new Random();

    public void main(String[] args) {
        Container origin = new Container(100, 5); // Create containers with elements and max capacity
        Container target = new Container(200, 10);

        // Schedule tasks to perform swaps concurrently
        executor.submit(() -> swap(origin, target, 3, 5000, TimeUnit.MILLISECONDS));
        executor.submit(() -> swap(target, origin, 5, 6000, TimeUnit.MILLISECONDS));

        // Shut down the executor when all tasks are completed or after a timeout
        try {
            executor.shutdown();
            if (!executor.awaitTermination(1, TimeUnit.MINUTES)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public boolean swap(Container origin, Container target, int numElements, long timeout, TimeUnit timeUnit) {
        ReentrantLock originLock = origin.getLock();
        ReentrantLock targetLock = target.getLock();

        // Try to acquire both locks with a random wait strategy and timeout
        long startTime = System.currentTimeMillis();
        while (true) {
            if (System.currentTimeMillis() - startTime > timeUnit.toMillis(timeout)) {
                return false; // Timeout elapsed, abort swap
            }

            try {
                long waitTime = randomWaitComponent(); // Calculate a random delay before retrying the lock acquisition
                if (originLock.tryLock(waitTime, timeUnit)) {
                    if (targetLock.tryLock(waitTime, timeUnit)) {
                        // Both locks acquired successfully, proceed with swap
                        boolean result = performSwap(origin, target, numElements);
                        originLock.unlock();
                        targetLock.unlock();
                        return result;
                    } else {
                        // Target lock acquisition failed, release origin lock and retry
                        originLock.unlock();
                    }
                } else {
                    // Origin lock acquisition failed, wait before retrying
                }
            } catch (InterruptedException e) {
                return false; // Swap interrupted, abort swap
            }

            try {
                Thread.sleep(waitTime); // Wait a bit before the next try
            } catch (InterruptedException e) {
                return false; // Interruption during wait, abort swap
            }
        }
    }

    private long randomWaitComponent() {
        return random.nextInt(500); // Generate a random delay from 0 to 499 ms
    }

    private boolean performSwap(Container origin, Container target, int numElements) {
        if (origin.getCount().value < numElements) {
            throw new InsufficientElementsException();
        }

        origin.removeElements(numElements); // Perform swap operation
        target.addElements(numElements);
        return true;
    }

    static class Container {
        private ElementCount count;
        private int maxCapacity;
        private ReentrantLock lock = new ReentrantLock();

        public Container(int initialElements, int maxCapacity) {
            this.count = new ElementCount(initialElements);
            this.maxCapacity = maxCapacity;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public ElementCount getCount() {
            return count;
        }

        public void removeElements(int numElements) {
            count.decrease(numElements); // Perform removal operation
        }

        public void addElements(int numElements) {
            count.increase(numElements); // Perform addition operation
        }
    }

    static class ElementCount {
        private int value;

        public ElementCount(int initialValue) {
            this.value = initialValue;
        }

        public synchronized void increase(int numElements) {
            if (value + numElements > maxCapacity) {
                throw new IllegalArgumentException("Exceeded container's maximum capacity");
            }
            value += numElements;
        }

        public synchronized void decrease(int numElements) {
            if (value - numElements < 0) {
                throw new IllegalStateException("Insufficient elements in the container");
            }
            value -= numElements;
        }

        public synchronized int value() {
            return value;
        }
    }

    static class InsufficientElementsException extends RuntimeException { }
