  public static boolean moveWidgets(Bin src, Bin dest, int numWidgets, long timeout, TimeUnit unit) {
    WidgetCount widgetCount = new WidgetCount(numWidgets);
    ReentrantLock srcLock = src.getLock();
    ReentrantLock destLock = dest.getLock();

    for (int i = 0; i < RETRIES; i++) {
      try {
        if (srcLock.tryLock(timeout, unit) && destLock.tryLock(timeout, unit)) {
          if (!src.hasEnoughWidgets(widgetCount)) throw new NotEnoughWidgetsException();
          src.removeWidgets(widgetCount);
          dest.addWidgets(widgetCount);
          srcLock.unlock();
