        Thread.sleep(delay);
      } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        return false;
      }
    }

    return false;
  }

  private static void releaseLocks(ReentrantLock... locks) {
    for (ReentrantLock lock : locks) {
      if (lock != null && lock.isHeldByCurrentThread()) lock.unlock();
    }
  }

  private static long calculateDelay(int attemptNumber) {
    return Math.min((1 << attemptNumber) + getRandomComponent(), TIMEOUT);
