    private void moveWidgets() throws InterruptedException, NotEnoughWidgetsException {
        Random random = new Random();
        long retryDelay = calculateRetryDelay(random);
        while (true) {
            if (tryAcquireLocks()) {
                synchronized (sourceBin) {
                    synchronized (targetBin) {
                        // Check if the source bin has enough widgets
                        int currentWidgetCount = sourceBin.widgetCount.count;
                        if (currentWidgetCount >= numWidgetsToMove) {
                            // Move widgets from source to target
