    public Bin(String name) {
        this.name = name;
        this.widgetCount = new WidgetCount();
        this.widgetCount.count = 0; // Assume initial count is zero
    }
}

class NotEnoughWidgetsException extends Exception {
    public NotEnoughWidgetsException(String message) {
        super(message);
    }
}

class WidgetMover implements Runnable {
    private final Bin sourceBin;
    private final Bin targetBin;
    private final int numWidgetsToMove;
    private final long timeoutDuration;
    private final TimeUnit timeUnit;

    public WidgetMover(Bin sourceBin, Bin targetBin, int numWidgetsToMove, long timeoutDuration, TimeUnit timeUnit) {
        this.sourceBin = sourceBin;
        this.targetBin = targetBin;
        this.numWidgetsToMove = numWidgetsToMove;
        this.timeoutDuration = timeoutDuration;
        this.timeUnit = timeUnit;
    }

    @Override
    public void run() {
        try {
            moveWidgets();
        } catch (InterruptedException | NotEnoughWidgetsException e) {
            System.out.println("Move interrupted: " + e.getMessage());
        }
    }

    private void moveWidgets() throws InterruptedException, NotEnoughWidgetsException {
        Random random = new Random();
        long retryDelay = calculateRetryDelay(random);
        while (true) {
            if (tryAcquireLocks()) {
                synchronized (sourceBin) {
                    synchronized (targetBin) {
                        // Check if the source bin has enough widgets
                        int currentWidgetCount = sourceBin.widgetCount.count;
                        if (currentWidgetCount >= numWidgetsToMove) {
                            // Move widgets from source to target
                            sourceBin.widgetCount.count -= numWidgetsToMove;
                            targetBin.widgetCount.count += numWidgetsToMove;
                            System.out.println("Moved " + numWidgetsToMove + " widgets from " + sourceBin.name + " to " + targetBin.name);
                        } else {
                            // Not enough widgets, throw custom exception
                            throw new NotEnoughWidgetsException("Not enough widgets in " + sourceBin.name);
                        }
                    }
                }
                return; // Locks acquired and widgets moved successfully
            } else {
                Thread.sleep(retryDelay); // Wait before retrying lock acquisition
                retryDelay = calculateRetryDelay(random); // Calculate new retry delay for next iteration
            }
        }
    }

    private boolean tryAcquireLocks() {
        ReentrantLock sourceLock = new ReentrantLock();
        ReentrantLock targetLock = new ReentrantLock();

        return sourceLock.tryLock(timeoutDuration, timeUnit) && targetLock.tryLock(timeoutDuration, timeUnit);
    }

    private long calculateRetryDelay(Random random) {
        long fixedDelay = 100; // Fixed delay component in milliseconds
        int randomPause = random.nextInt(200); // Random pause component in milliseconds (0-199)
        return fixedDelay + randomPause;
    }

