import java.util.concurrent.*;
import java.util.Map;
import java.util.HashMap;

public class PublishingVehicleTracker {
    private final Map<String, SafePoint> coordinates = new ConcurrentHashMap<>();

    public void refresh(String vehicleId, int x, int y) throws IllegalArgumentException {
        if (!coordinates.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle " + vehicleId + " does not exist");
        }
        coordinates.put(vehicleId, new SafePoint(x, y));
    }

    public Map<String, SafePoint> getAllCoordinates() {
        return Collections.unmodifiableMap(coordinates);
    }

    public SafePoint getCoordinatesById(String vehicleId) throws IllegalArgumentException {
        if (!coordinates.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle " + vehicleId + " does not exist");
        }
        return coordinates.get(vehicleId);
    }

    public void updateCoordinatesById(String vehicleId, int x, int y) throws IllegalArgumentException {
        if (!coordinates.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle " + vehicleId + " does not exist");
        }
        SafePoint point = coordinates.get(vehicleId);
        point.setX(x);
        point.setY(y);
    }

