public class PublishingVehicleTracker {

    private Map<String, SafePoint> vehicleCoordinates = new HashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(2);

    public synchronized void updateVehicleCoordinates(String vehicleId, double x, double y) {
        if (vehicleCoordinates.containsKey(vehicleId)) {
            SafePoint sp = new SafePoint(x, y);
            executorService.submit(() -> vehicleCoordinates.put(vehicleId, sp));
        } else {
            throw new RuntimeException("Vehicle ID not found");
        }
