    public void addRune(Rune rune) {
        runes.add(rune);
    }

    public List<Harmony> crystallizeRunes() {
        List<Harmony> harmonies = new ArrayList<>();
        Collections.sort(runes, Comparator.comparing(Rune::getConstellation).thenComparing(Rune::getResonance));

        int i = 0;
        while (i < runes.size()) {
            for (int j = i + 1; j < runes.size(); j++) {
                if (runes.get(i).getConstellation() == runes.get(j).getConstellation() &&
                        (runes.get(i).getResonance() == Rune.Resonance.OPPOSITE || runes.get(i).getResonance() == Rune.Resonance.ANTIPODAL) &&
                        (runes.get(j).getResonance() == Rune.Resonance.ANTIPODAL || runes.get(j).getResonance() == Rune.Resonance.OPPOSITE)) {
                    harmonies.add(new Harmony(runes.get(i), runes.get(j)));
                }
            }
            i++;
        }

        return harmonies;
    }
}

public class GrimoireCrystallizer {
    private final Grimoire grimoire = new Grimoire();

    private void channelTheGrimoire(Collection<Rune> candidateRunes) {
        ExecutorService executor = Executors.newFixedThreadPool(Math.min(3, Math.max(candidateRunes.size(), 2)));
        List<Future<List<Harmony>>> futures = new ArrayList<>();

        for (Rune rune : candidateRunes) {
            futures.add(executor.submit(() -> {
                grimoire.addRune(rune);
                return grimoire.crystallizeRunes();
            }));
        }

        for (Future<List<Harmony>> future : futures) {
            try {
                future.get().forEach(harmony -> System.out.println("Formed harmony: " + harmony));
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executor.shutdownNow();
