        List<Rune> candidateRunes = Arrays.asList(
                new Rune(Rune.Constellation.AIR, Rune.Resonance.OPPOSITE),
                new Rune(Rune.Constellation.FIRE, Rune.Resonance.ANTIPODAL),
                new Rune(Rune.Constellation.EARTH, Rune.Resonance.SYMMETRIC),
