public class Grimoire {

    private List<Rune> runes;

    public Grimoire(List<Rune> runes) {
        this.runes = runes;
    }

    public int channelTheGrimoire() {
        int count = 0;
        Collections.sort(runes, new Comparator<Rune>() {
            @Override
            public int compare(Rune o1, Rune o2) {
                if (o1.getConstellation().equals(o2.getConstellation())) {
                    return Integer.compare(o1.getResonance(), o2.getResonance());
                } else {
                    return 0;
                }
            }
        });

        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<Future<Integer>> futures = new ArrayList<>();
        for (int i = 1; i < runes.size(); i += 2) {
            futures.add(executor.submit(new HarmonyChecker(runes.get(i), runes.get(i - 1))));
        }

        try {
            for (Future<Integer> future : futures) {
                count += future.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Failed to calculate harmonies", e);
        } finally {
            executor.shutdownNow();
        }

        return count;
    }

    private static class HarmonyChecker implements Callable<Integer> {

        private final Rune rune1, rune2;

        public HarmonyChecker(Rune rune1, Rune rune2) {
            this.rune1 = rune1;
            this.rune2 = rune2;
        }

        @Override
        public Integer call() {
            if (rune1.getResonance() == -(rune2.getResonance())) {
                return 1;
            } else {
                return 0;
            }
        }
    }

