import java.util.*;
import java.util.concurrent.*;

class MysticBeastTracker {
    private final ConcurrentHashMap<String, Glyph> beasts;
    private static final int MAX_THREADS = 5;

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        beasts = new ConcurrentHashMap<>(initialPerches);
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(beasts);
    }

    public Glyph getPerch(String sigil) {
        return beasts.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Glyph newGlyph = new Glyph(spark, glimmer);
        if (!beasts.containsKey(sigil)) {
            throw new IllegalArgumentException("Beast does not exist");
        }
        beasts.put(sigil, newGlyph);
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(beasts));
    }

    private static class Task implements Runnable {
        private final MysticBeastTracker tracker;
        private final String sigil;
        private final Glyph newGlyph;

        public Task(MysticBeastTracker tracker, String sigil, int spark, int glimmer) {
            this.tracker = tracker;
            this.sigil = sigil;
            this.newGlyph = new Glyph(spark, glimmer);
        }

        @Override
        public void run() {
            tracker.beasts.put(sigil, newGlyph);
        }
    }

    private static class Glyph {
        private final int spark;
        private final int glimmer;

        public Glyph(int spark, int glimmer) {
            this.spark = spark;
            this.glimmer = glimmer;
        }

        @Override
        public String toString() {
            return "Glyph{" +
                    "spark=" + spark +
                    ", glimmer=" + glimmer +
                    '}';
        }
    }
}

class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Map<String, MysticBeastTracker.Glyph> initialPerches = new HashMap<>();
        initialPerches.put("Beast1", new MysticBeastTracker.Glyph(2, 3));
        initialPerches.put("Beast2", new MysticBeastTracker.Glyph(5, 7));

        MysticBeastTracker tracker = new MysticBeastTracker(initialPerches);

        System.out.println("Initial perches: " + tracker.getPerches());
        System.out.println("Beast1's perch: " + tracker.getPerch("Beast1"));

        List<Future<?>> futures = new ArrayList<>();
        ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREADS);

        for (int i = 3; i <= 8; i++) {
            String sigil = "Beast" + i;
            Future<?> future = executorService.submit(new MysticBeastTracker.Task(tracker, sigil, i, 2 * i));
            futures.add(future);
        }

        for (Future<?> future : futures) {
            future.get();
        }

        System.out.println("Updated perches: " + tracker.getPerches());

        executorService.shutdownNow();
    }
}

