interface GoldAmount {
    double getGold();
}

class Vault implements GoldAmount {
    private double gold;

    public Vault(double initialGold) {
        this.gold = initialGold;
    }

    @Override
    public double getGold() {
        return this.gold;
    }

    public synchronized void debit(double amount) throws InsufficientTreasureException {
        if (amount > gold) throw new InsufficientTreasureException();
        this.gold -= amount;
    }

    public synchronized void credit(double amount) {
        this.gold += amount;
    }

    @Override
    public int hashCode() {
        return Objects.hash(this);
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == null || !Vault.class.isAssignableFrom(obj.getClass())) return false;
        Vault other = (Vault) obj;
        return Double.compare(this.gold, other.gold) == 0;
    }
}

class InsufficientTreasureException extends Exception { }

interface TreasureTransferRitual {
    void transfer(double amount, Vault fromVault, Vault toVault);
}

class DefaultTreasureTransferRitual implements TreasureTransferRitual {
    @Override
    public void transfer(double amount, Vault fromVault, Vault toVault) {
        if (fromVault.equals(toVault)) throw new AssertionError("Cannot transfer between the same vault");

        if (fromVault.getGold() < amount || toVault.getGold() > Double.MAX_VALUE - amount) return;

        int fromHash = System.identityHashCode(fromVault);
        int toHash = System.identityHashCode(toVault);

        // Introduce secondary tie-breaking lock if both vaults have the same hash code
        if (fromHash == toHash) synchronized (this) {
            try {
                fromVault.debit(amount);
                toVault.credit(amount);
            } catch (InsufficientTreasureException e) { }
        } else if (fromHash < toHash) { // Ensure consistent lock acquisition order
            synchronized (fromVault) {
                synchronized (toVault) {
                    try {
                        fromVault.debit(amount);
                        toVault.credit(amount);
                    } catch (InsufficientTreasureException e) { }
                }
            }
        } else { // Ensure consistent lock acquisition order
            synchronized (toVault) {
                synchronized (fromVault) {
                    try {
                        fromVault.debit(amount);
                        toVault.credit(amount);
                    } catch (InsufficientTreasureException e) { }
                }
            }
        }
    }
}

public class Main {
    public static void main(String[] args) {
        final Vault fromVault = new Vault(1000.0);
        final Vault toVault = new Vault(500.0);

        TreasureTransferRitual ritual = new DefaultTreasureTransferRitual();

        new Thread(() -> { // Transfer 300 gold from fromVault to toVault in a separate thread
            ritual.transfer(300, fromVault, toVault);
            System.out.println("Transferred 300 gold from " + fromVault + " to " + toVault);
        }).start();

        // Transfer remaining gold (700) from fromVault to toVault in the main thread
        ritual.transfer(fromVault.getGold(), fromVault, toVault);
        System.out.println("Transferred all gold from " + fromVault + " to " + toVault);
    }
}

import java.util.concurrent.locks.ReentrantLock;

interface Vault {
    long getBalance();
}

interface GoldAmount {
    boolean transferTo(Vault vault, long amount);
}

class InsufficientTreasureException extends Exception {
    InsufficientTreasureException(String message) {
        super(message);
    }
}

class VaultImpl implements Vault {
    private final ReentrantLock lock = new ReentrantLock();
    private long balance;

    public VaultImpl(long initialBalance) {
        this.balance = initialBalance;
    }

    @Override
    public long getBalance() {
        lock.lock();
        try {
            return balance;
        } finally {
            lock.unlock();
        }
    }

    public void addGold(long amount) {
        lock.lock();
        try {
            balance += amount;
        } finally {
            lock.unlock();
        }
    }

    public boolean removeGold(long amount) throws InsufficientTreasureException {
        lock.lock();
        try {
            if (amount <= balance) {
                balance -= amount;
                return true;
            } else {
                throw new InsufficientTreasureException("Not enough gold in the vault.");
            }
        } finally {
            lock.unlock();
        }
    }
}

class GoldTransferRitual implements GoldAmount {
    private final Vault from;
    private final Vault to;

    public GoldTransferRitual(Vault from, Vault to) {
        this.from = from;
        this.to = to;
    }

    @Override
    public boolean transferTo(Vault vault, long amount) {
        if (vault == null || amount <= 0) {
            return false;
        }

        long fromId = System.identityHashCode(from);
        long toId = System.identityHashCode(to);

        // Ensure consistent lock acquisition order, using hash codes as tie-breaker
        if (fromId > toId) {
            Vault temp = from;
            from = to;
            to = temp;
        }

        ReentrantLock firstLock, SecondLock;

        if (System.identityHashCode(from) == System.identityHashCode(to)) {
            FirstLock = new ReentrantLock();
            SecondLock = FirstLock;
        } else {
            FirstLock = new ReentrantLock();
            SecondLock = new ReentrantLock();
        }

        FirstLock.lock();
        try {
            if (from.getBalance() >= amount) {
                to.addGold(amount);
                ((VaultImpl) from).removeGold(amount);
                SecondLock.lock();
                try {
                    return true;
                } finally {
                    SecondLock.unlock();
                }
            } else {
                return false;
            }
        } finally {
            FirstLock.unlock();
        }
    }

    public static void main(String[] args) throws InsufficientTreasureException {
        VaultImpl vault1 = new VaultImpl(1000);
        VaultImpl vault2 = new VaultImpl(500);

        GoldTransferRitual ritual = new GoldTransferRitual(vault1, vault2);

        if (ritual.transferTo(vault2, 300)) {
            System.out.println("Transaction successful");
        } else {
            System.out.println("Insufficient treasure in the from vault");
        }

        System.out.println("Vault1 balance: " + vault1.getBalance());
        System.out.println("Vault2 balance: " + vault2.getBalance());
    }
}

interface Vault {
    int getHashCode();
    void performTransfer(GoldAmount gold, Vault toVault) throws InsufficientTreasureException;
}

interface GoldAmount {
    boolean debitFromVault(Vault vault) throws InsufficientTreasureException;
    void creditToVault(Vault vault);
}

class VaultImpl implements Vault {
    private final int hashCode;
    private final GoldAmount gold;

    public VaultImpl(int hashCode, GoldAmount gold) {
        this.hashCode = hashCode;
        this.gold = gold;
    }

    @Override
    public int getHashCode() {
        return hashCode;
    }

    @Override
    public void performTransfer(GoldAmount gold, Vault toVault) throws InsufficientTreasureException {
        if (this.hashCode == toVault.getHashCode()) {
            synchronized (new Object[]{gold, this}) { // Use an array of objects to create a consistent lock sequence
                if (!gold.debitFromVault(this)) {
                    throw new InsufficientTreasureException("Insufficient treasure in vault " + hashCode);
                }
                toVault.performTransferHelper();
            }
        } else {
            synchronized (this) {
                if (!gold.debitFromVault(this)) {
                    throw new InsufficientTreasureException("Insufficient treasure in vault " + hashCode);
                }
                toVault.performTransferHelper();
            }
        }
    }

    private void performTransferHelper() {
        gold.creditToVault(this);
    }
}

class GoldAmountImpl implements GoldAmount {
    private int treasure;

    public GoldAmountImpl(int treasure) {
        this.treasure = treasure;
    }

    @Override
    public boolean debitFromVault(Vault vault) throws InsufficientTreasureException {
        if (treasure > 0) {
            treasure--;
            return true;
        } else {
            throw new InsufficientTreasureException("Insufficient treasure");
        }
    }

    @Override
    public void creditToVault(Vault vault) {
        ((VaultImpl) vault).performTransferHelper();
    }
}

class InsufficientTreasureException extends Exception {
    public InsufficientTreasureException(String message) {
        super(message);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        Vault vault1 = new VaultImpl(123, new GoldAmountImpl(10));
        Vault vault2 = new VaultImpl(456, new GoldAmountImpl(20));

        Thread thread1 = new Thread(() -> {
            try {
                vault1.performTransfer(new GoldAmountImpl(3), vault2);
            } catch (InsufficientTreasureException e) {
                System.out.println("Error in transferring gold from vault 1 to vault 2: " + e.getMessage());
            }
        });

        Thread thread2 = new Thread(() -> {
            try {
                vault2.performTransfer(new GoldAmountImpl(4), vault1);
            } catch (InsufficientTreasureException e) {
                System.out.println("Error in transferring gold from vault 2 to vault 1: " + e.getMessage());
            }
        });

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();

        System.out.println("Treasure in vault 1: " + ((VaultImpl) vault1).gold.treasure);
        System.out.println("Treasure in vault 2: " + ((VaultImpl) vault2).gold.treasure);
    }
}

