import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class LLMC {
private static final Object tieLock = new Object();

public void transferMoney(final Account fromAcct,
final Account toAcct,
final DollarAmount amount)
throws InsufficientFundsException {
class Helper {
public void transfer() throws InsufficientFundsException {
if (fromAcct.getBalance().compareTo(amount) < 0)
throw new InsufficientFundsException();
else {
fromAcct.debit(amount);
toAcct.credit(amount);
}
}
}

int fromHash = System.identityHashCode(fromAcct);
int toHash = System.identityHashCode(toAcct);

if (fromHash < toHash) {
synchronized (fromAcct) {
synchronized (toAcct) {
new Helper().transfer();
}
}
} else if (fromHash > toHash) {
synchronized (toAcct) {
synchronized (fromAcct) {
new Helper().transfer();
}
}
} else {
synchronized (tieLock) {
synchronized (fromAcct) {
synchronized (toAcct) {
new Helper().transfer();
}
}
}
}
}

public static class DollarAmount implements Comparable<DollarAmount> {
private final BigDecimal value;

public DollarAmount(BigDecimal value) {
this.value = value;
}

public DollarAmount add(DollarAmount other) {
return new DollarAmount(this.value.add(other.value));
}

public DollarAmount subtract(DollarAmount other) {
return new DollarAmount(this.value.subtract(other.value));
}

@Override
public int compareTo(DollarAmount other) {
return this.value.compareTo(other.value);
}

@Override
public String toString() {
return value.toString();
}
}

public interface Account {
void debit(DollarAmount d);

void credit(DollarAmount d);

DollarAmount getBalance();

int getAcctNo();
}

public static class AccountImpl implements Account {
private DollarAmount balance;
private final int acctNo;

public AccountImpl(int acctNo, DollarAmount initialBalance) {
this.acctNo = acctNo;
this.balance = initialBalance;
}

@Override
public synchronized void debit(DollarAmount d) {
balance = balance.subtract(d);
}

@Override
public synchronized void credit(DollarAmount d) {
balance = balance.add(d);
}

@Override
public synchronized DollarAmount getBalance() {
return balance;
}

@Override
public int getAcctNo() {
return acctNo;
}
}

static class InsufficientFundsException extends Exception {
public InsufficientFundsException() {
super("Insufficient funds in account.");
}
}

public static void main(String[] args) throws InterruptedException {
LLMC service = new LLMC();

Account a1 = new AccountImpl(1, new DollarAmount(new BigDecimal("1000.00")));
Account a2 = new AccountImpl(2, new DollarAmount(new BigDecimal("1000.00")));

Runnable task = () -> {
try {
// Reduced iterations to 2 for faster completion
for (int i = 0; i < 2; i++) {
service.transferMoney(a1, a2, new DollarAmount(new BigDecimal("1.00")));
service.transferMoney(a2, a1, new DollarAmount(new BigDecimal("1.00")));
}
} catch (InsufficientFundsException e) {
e.printStackTrace();
}
};

// Reduced thread pool size to 2 to reduce thread overhead
ExecutorService executor = Executors.newFixedThreadPool(2);
// Reduced number of tasks to 2
for (int i = 0; i < 2; i++) {
executor.submit(task);
}

executor.shutdown();
while (!executor.isTerminated()) {
Thread.sleep(10);
}

System.out.println("Final balance of Account 1: " + ((AccountImpl) a1).getBalance());
System.out.println("Final balance of Account 2: " + ((AccountImpl) a2).getBalance());
}
}

