class Hoard {
    private int gems;

    public Hoard(int gems) {
        this.gems = gems;
    }

    public synchronized void depositGems(GemAmount amount) throws InsufficientGemsException {
        if (amount.get() > gems) {
            throw new InsufficientGemsException("Not enough gems in the hoard.");
        }
        this.gems -= amount.get();
    }

    public synchronized void withdrawGems(GemAmount amount) throws InsufficientGemsException {
        if (amount.get() > gems) {
            throw new InsufficientGemsException("Not enough gems in the hoard.");
        }
        this.gems += amount.get();
    }

    @Override
    public int hashCode() {
        return System.identityHashCode(this);
    }
}

interface GemAmount {
    int get();
}

class SimpleGemAmount implements GemAmount {
    private final int value;

    public SimpleGemAmount(int value) {
        this.value = value;
    }

    @Override
    public int get() {
        return this.value;
    }
}

class InsufficientGemsException extends Exception {
    public InsufficientGemsException(String message) {
        super(message);
    }
}

class GemTransferHelper {
    private final Hoard sourceHoard;
    private final Hoard destinationHoard;

    public GemTransferHelper(Hoard sourceHoard, Hoard destinationHoard) {
        this.sourceHoard = sourceHoard;
        this.destinationHoard = destinationHoard;
    }

    public void transferGems(GemAmount amount) throws InsufficientGemsException {
        int hashCode1 = sourceHoard.hashCode();
        int hashCode2 = destinationHoard.hashCode();

        if (hashCode1 > hashCode2) {
            synchronized (sourceHoard) {
                synchronized (destinationHoard) {
                    transferGemsUnsafe(amount);
                }
            }
        } else if (hashCode1 < hashCode2) {
            synchronized (destinationHoard) {
                synchronized (sourceHoard) {
                    transferGemsUnsafe(amount);
                }
            }
        } else { // If hash codes are equal, use a secondary tie-breaking lock
            Object secondaryLock = new Object();

            if (Thread.currentThread().getId() % 2 == 0) {
                synchronized (sourceHoard) {
                    synchronized (secondaryLock) {
                        synchronized (destinationHoard) {
                            transferGemsUnsafe(amount);
                        }
                    }
                }
            } else {
                synchronized (destinationHoard) {
                    synchronized (secondaryLock) {
                        synchronized (sourceHoard) {
                            transferGemsUnsafe(amount);
                        }
                    }
                }
            }
        }
