import java.util.concurrent.Semaphore;

public class SemaphoreBoundedBuffer<E> {
private final Semaphore availableItems, availableSpaces;
private final E[] items;
private int putPosition = 0, takePosition = 0;

public SemaphoreBoundedBuffer(int capacity) {
if (capacity <= 0) throw new IllegalArgumentException();
availableItems = new Semaphore(0);
availableSpaces = new Semaphore(capacity);
items = (E[]) new Object[capacity];
}

public void put(E x) throws InterruptedException {
availableSpaces.acquire();
synchronized (this) {
items[putPosition] = x;
putPosition = (putPosition + 1) % items.length;
}
availableItems.release();
}

public E take() throws InterruptedException {
availableItems.acquire();
E item;
synchronized (this) {
item = items[takePosition];
items[takePosition] = null;
takePosition = (takePosition + 1) % items.length;
}
availableSpaces.release();
return item;
}

public static void main(String[] args) {
final int bufferSize = 2;
final int numItems = 2;

SemaphoreBoundedBuffer<Integer> buffer = new SemaphoreBoundedBuffer<>(bufferSize);

Thread producer = new Thread(() -> {
try {
for (int i = 0; i < numItems; i++) {
buffer.put(i);
// Avoid printing to reduce state space
}
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
