import java.util.LinkedList;
import java.util.concurrent.Semaphore;

public class PotionLoop {
    private final LinkedList<Potion> loop = new LinkedList<>();
    private final Semaphore availableSlots;
    private final Semaphore openSlots;

    public PotionLoop(int capacity) {
        this.availableSlots = new Semaphore(capacity);
        this.openSlots = new Semaphore(0, true);
    }

    public void put(Potion x) throws InterruptedException {
        openSlots.acquire(); // Block if no open slots available
        loop.add(x);
        availableSlots.release(); // Notify that a slot is now open
    }

    public Potion take() throws InterruptedException {
        availableSlots.acquire(); // Block if no potions available
        Potion x = loop.removeFirst();
        openSlots.release(); // Notify that a slot is now open
        return x;
    }

    public boolean isEmpty() {
        synchronized (loop) {
            return loop.isEmpty();
        }
    }

    public boolean isFull() {
        synchronized (loop) {
            return loop.size() == availableSlots.availablePermits();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        PotionLoop potionLoop = new PotionLoop(5);

        // Create alchemists as threads to interact with the potion loop
        Thread alchemist1 = new Thread(() -> {
            try {
                potionLoop.put(new Potion());
                System.out.println("Alchemist 1 added a potion");
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });

        Thread alchemist2 = new Thread(() -> {
            try {
                Potion potion = potionLoop.take();
                System.out.println("Alchemist 2 took a potion");
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });

        Thread alchemist3 = new Thread(() -> {
            try {
                potionLoop.put(new Potion());
                System.out.println("Alchemist 3 added a potion");
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });

        // Start alchemists' threads
        alchemist1.start();
        alchemist2.start();
        alchemist3.start();

        // Join alchemists' threads to wait for them to finish
        alchemist1.join();
        alchemist2.join();
        alchemist3.join();

        System.out.println("Potion loop is empty: " + potionLoop.isEmpty());
    }

    private static class Potion {} // Placeholder for potion object
}

import java.util.concurrent.Semaphore;

public class PotionLoop {
    private final int size;
    private final Potion[] potions;
    private int count;
    private int head, tail;
    private Semaphore availablePotions, openSlots;

    public PotionLoop(int size) {
        if (size <= 0) throw new IllegalArgumentException("Size must be positive");
        this.size = size;
        potions = new Potion[size];
        count = 0;
        head = tail = 0;
        availablePotions = new Semaphore(0);
        openSlots = new Semaphore(size);
    }

    public synchronized void put(Potion potion) {
        try {
            openSlots.acquire();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Failed to acquire open slot");
        }
        potions[tail] = potion;
        tail = (tail + 1) % size;
        count++;
        availablePotions.release();
    }

    public synchronized Potion take() {
        try {
            availablePotions.acquire();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Failed to acquire available potion");
        }
        Potion potion = potions[head];
        potions[head] = null;
        head = (head + 1) % size;
        count--;
        openSlots.release();
        return potion;
    }

    public synchronized boolean isEmpty() {
        return count == 0;
    }

    public synchronized boolean isFull() {
        return count == size;
    }

    public static void main(String[] args) {
        PotionLoop loop = new PotionLoop(3);

        new Thread(() -> {
            loop.put(new Potion("A"));
            loop.put(new Potion("B"));
            System.out.println(loop.take().getName()); // Output: A
            System.out.println(loop.take().getName()); // Output: B
        }).start();

        new Thread(() -> {
            loop.put(new Potion("C"));
            loop.put(new Potion("D"));
            System.out.println(loop.take().getName()); // Output: C
            loop.put(new Potion("E"));
            System.out.println(loop.take().getName()); // Output: D
            System.out.println(loop.take().getName()); // Output: E
        }).start();

        new Thread(() -> {
            loop.put(new Potion("F"));
            loop.put(new Potion("G"));
            System.out.println(loop.take().getName()); // Output: F
            System.out.println(loop.take().getName()); // Output: G
        }).start();

        // Main thread waits for all threads to finish
    }
}

