import java.util.concurrent.Semaphore;

public class PotionLoop {

    private int maxPotions;
    private int currentIndex = -1;
    private Potion[] potions;
    private Semaphore availableCount;
    private Semaphore openSlots;

    public PotionLoop(int maxPotions) {
        this.maxPotions = maxPotions;
        this.potions = new Potion[maxPotions];
        this.availableCount = new Semaphore(0);
        this.openSlots = new Semaphore(maxPotions);
    }

    public void put(Potion potion) throws InterruptedException {
        openSlots.acquire(); // block if there are no open slots
        synchronized (this) {
            currentIndex = (currentIndex + 1) % maxPotions;
            potions[currentIndex] = potion;
            if (availableCount.tryAcquire(maxPotions - availableCount.availablePermits(), 0)) {
                notifyAll(); // notify all threads that a new potion is available
            } else {
                // If we are the first one to put, notify all waiting threads to check if they can add next
                if (currentIndex == 0) {
                    availableCount.release(maxPotions - 1);
                    notifyAll(); // notify All threads that a new potion is available
                }
            }
        }
    }

    public Potion take() throws InterruptedException {
        if (isEmpty()) {
            return null; // return null if the loop is empty
        }
        availableCount.acquire(); // block if there are no available potions
        synchronized (this) {
            Potion potion = potions[currentIndex];
            potions[currentIndex] = null;
            if (openSlots.tryAcquire(maxPotions - openSlots.availablePermits(), 0)) {
                notifyAll(); // notify All threads that a new slot is available
            } else {
                // If we are the Last one to take, notify All waiting threads to check if they can add next
                if (currentIndex == maxPotions - 1) {
                    openSlots.release(maxPotions - 1);
                    notifyAll(); // notify All threads that a new slot is available
                }
            }
            return potion;
        }
    }

    public synchronized boolean isEmpty() {
        for (int i = 0; i < maxPotions; ++i) {
            if (potions[i] != null) {
                return false;
            }
        }
        return true;
    }

    public synchronized boolean isFull() {
        for (int i = 0; i < maxPotions; ++i) {
            if (potions[i] == null) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Example usage of the PotionLoop class
        PotionLoop potionLoop = new PotionLoop(10);
        Thread alchemist1 = new Thread(() -> {
            try {
                potionLoop.put(new Potion()); // add a potion to the loop
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });
        Thread alchemist2 = new Thread(() -> {
            try {
                potionLoop.take(); // remove and return a potion from the loop
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        });
        alchemist1.start();
        alchemist2.start();
    }
}

