        try {
            artifactMap.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public Artifact getArtifact(String key) {
        lock.readLock().lock();
        try {
            return artifactMap.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return artifactMap.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return artifactMap.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(String key) {
