        try {
            return artifactMap.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Artifact value) {
        lock.readLock().lock();
        try {
            return artifactMap.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    private static class Artifact {} // dummy class to represent artifacts

    public static void main(String[] args) throws InterruptedException {
        // create a sample artifact map
        Map<String, Artifact> artifactMap = new HashMap<>();
        artifactMap.put("ring", new Artifact());
        artifactMap.put("amulet", new Artifact());

        // create an EnchantedRegistry instance
        EnchantedRegistry registry = new EnchantedRegistry(artifactMap);

        // start a thread to put artifacts
        Thread putter = new Thread(() -> {
