import java.util.*;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class EnchantedRegistry {
    private Map<String, String> artifacts;
    private ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public EnchantedRegistry(Map<String, String> artifacts) {
        this.artifacts = artifacts;
    }

    public void putArtifact(String key, String value) {
        lock.writeLock().lock();
        try {
            artifacts.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void removeArtifact(String key) {
        lock.writeLock().lock();
        try {
            artifacts.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public String getArtifact(String key) {
        lock.readLock().lock();
        try {
            return artifacts.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void putAllArtifacts(Map<String, String> newArtifacts) {
        lock.writeLock().lock();
        try {
            artifacts.putAll(newArtifacts);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void clearArtifacts() {
        lock.writeLock().lock();
        try {
            artifacts.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return artifacts.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return artifacts.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(String key) {
        lock.readLock().lock();
        try {
            return artifacts.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(String value) {
        lock.readLock().lock();
        try {
            return artifacts.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) {
        Map<String, String> artifacts = new HashMap<>();
        artifacts.put("sword", "magic");
        EnchantedRegistry registry = new EnchantedRegistry(artifacts);

        Thread crafter = new Thread(() -> {
            registry.putArtifact("axe", "unbreakable");
            registry.removeArtifact("sword");
        });

        Thread observer1 = new Thread(() -> {
            System.out.println(registry.getArtifact("axe"));
        });

        Thread observer2 = new Thread(() -> {
            System.out.println(registry.containsKey("sword"));
        });

        crafter.start();
        observer1.start();
        observer2.start();

        try {
            crafter.join();
            observer1.join();
            observer2.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
