import java.util.concurrent.*;

public class MysticCounter {
    private int essence;

    public synchronized int get() {
        return this.essence;
    }

    public synchronized int compareAndSwap(int expectedEssence, int newEssence) {
        int oldEssence = this.essence;
        if (oldEssence == expectedEssence) {
            this.essence = newEssence;
        }
        return oldEssence;
    }

    public synchronized boolean compareAndSet(int expectedEssence, int newEssence) {
        if (compareAndSwap(expectedEssence, newEssence) == expectedEssence) {
            return true;
        } else {
            return false;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        MysticCounter mysticCounter = new MysticCounter();
        ExecutorService executorService = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            for (int i = 0; i < 1000; i++) {
                mysticCounter.compareAndSet(0, 1);
            }
        };

        Runnable task2 = () -> {
            for (int i = 0; i < 1000; i++) {
                mysticCounter.compareAndSet(1, 0);
            }
        };

        executorService.execute(task1);
        executorService.execute(task2);

        executorService.shutdown();
        executorService.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        System.out.println("Final essence: " + mysticCounter.get());
    }
