import java.util.*;

public class ChronomanticDragonTracker {
    private Constellation<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    public synchronized Constellation<String, MutableOrb> getConstellations() {
        return new Constellation<>(constellation);
    }

    public synchronized MutableOrb getOrb(String sigil) {
        MutableOrb orb = constellation.getValue(sigil);
        if (orb == null) {
            return null;
        }
        return new MutableOrb(orb);
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) throws IllegalArgumentException {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found");
        }
        MutableOrb orb = getOrb(sigil);
        orb.setShimmerX(shimmerX);
        orb.setShimmerY(shimmerY);
    }

    private static <T> Constellation<String, T> deepClone(Constellation<String, T> original) {
        Map<String, T> clonedMap = new HashMap<>();
        for (Map.Entry<String, T> entry : original.entrySet()) {
            clonedMap.put(entry.getKey(), deepCopy(entry.getValue()));
        }
        return new Constellation<>(clonedMap);
    }

    private static <T extends Cloneable> T deepCopy(T original) throws CloneNotSupportedException {
        @SuppressWarnings("unchecked")
        T copy = (T) original.clone();
        return copy;
    }

    public static void main(String[] args) {
        Constellation<String, MutableOrb> initialConstellation = new Constellation<>(Map.of(
            "dragon1", new MutableOrb(10, 20),
            "dragon2", new MutableOrb(30, 40)
        ));

