import java.util.Random;

public class GoblinGoldShuffle {
    private static final int MAX_POUCHES = 5;
    private static final int MAX_SWAPS = 10;
    private static final int MAX_THREADS = 3;

    static class GoldClump {
        private long amount;
        public GoldClump(long amount) { this.amount = amount; }
        public void setAmount(long amount) { this.amount = amount; }
        public long getAmount() { return amount; }
    }

    static class GoblinPouch {
        private static final Random random = new Random();
        private GoldClump goldClump;
        public GoblinPouch(GoldClump goldClump) { this.goldClump = goldClump; }
        public synchronized long getAmount() { return goldClump.getAmount(); }
        public synchronized void setAmount(long amount) { goldClump.setAmount(amount); }
    }

    static class SneakyTrade {
        private static final Random random = new Random();
        private static boolean isSneaky() { return random.nextBoolean(); }
        public static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            if (IsSneaky()) {
                synchronized (from) {
                    if (amount.getAmount() > from.getAmount()) throw new InsufficientGoldException();
                    synchronized (to) {
                        long newFrom = from.getAmount() - amount.getAmount();
                        long newTo = to.getAmount() + amount.getAmount();
                        from.setAmount(newFrom);
                        to.setAmount(newTo);
                    }
                }
            } else {
