        public TradeThread(GoblinPouch[] pouches) { this.pouches = pouches; }
        @Override
        public void run() {
            for (int i = 0; i < MAX_SWAPS; ++i) {
                int fromIndex = random.nextInt(MAX_POUCHES);
                int toIndex = random.nextInt(MAX_POUCHES);
                if (fromIndex == toIndex) continue;
                GoldClump amount = new GoldClump(random.nextLong());
                try {
                    SneakyTrade.transferGold(pouches[fromIndex], pouches[toIndex], amount);
                } catch (InsufficientGoldException e) {}
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
