            return Integer.compare(this.amount, other.amount);
        }

        public DollarAmount add(DollarAmount other) throws InsufficientFundsException {
            if (other.amount > this.amount) {
                throw new InsufficientFundsException();
            } else {
                return new DollarAmount(this.amount + other.amount);
            }
        }

        public DollarAmount subtract(DollarAmount other) throws InsufficientFundsException {
