        if (!lock.tryLock()) {
            return false;
        }
        boolean result = false;
        try {
            result = destination.transferFrom(this, amount, timeout, timeUnit);
        } finally {
            lock.unlock();
        }
        return result;
    }

    private boolean transferFrom(Account source, DollarAmount amount, long timeout, TimeUnit timeUnit) throws InsufficientFundsException {
        if (!source.lock.tryLock()) {
            throw new InsufficientFundsException("Insufficient funds");
        }
        boolean result = false;
        try {
            result = source.balance.getValue() >= amount.getValue();
            if (result) {
                source.balance = new DollarAmount(source.balance.getValue() - amount.getValue());
                destination.balance = new DollarAmount(destination.balance.getValue() + amount.getValue());
            }
        } finally {
            source.lock.unlock();
        }
        return result;
    }

    public DollarAmount getBalance() {
        return balance;
    }
}

