    public synchronized void run() {
        synchronized (mutex) {
            if (!started) {
                started = true;
                startTime = System.nanoTime();
                mutex.notifyAll();
            } else {
                endTime = System.nanoTime();
            }
        }
    }

    public synchronized long getTime() {
        return endTime - startTime;
