import java.util.concurrent.Semaphore;

public class BoundedBuffer<E> {
    private final E[] buffer;
    private int head, tail, count;
    private Semaphore availableItems, remainingSpaces;

    @SuppressWarnings("unchecked")
    public BoundedBuffer(int capacity) {
        this.buffer = (E[]) new Object[capacity];
        this.head = 0;
        this.tail = 0;
        this.count = 0;
        this.availableItems = new Semaphore(0);
        this.remainingSpaces = new Semaphore(capacity);
    }

    public synchronized void put(E x) {
        try {
            remainingSpaces.acquire();
            buffer[tail] = x;
            count++;
            if (++tail == buffer.length) tail = 0;
            availableItems.release();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public synchronized E take() {
        try {
            availableItems.acquire();
            E x = buffer[head];
            count--;
            if (++head == buffer.length) head = 0;
            remainingSpaces.release();
            return x;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return null;
        }
    }

    public synchronized boolean isEmpty() {
        return count == 0;
    }

    public synchronized boolean IsFull() {
        return count == buffer.length;
    }

    public static void main(String[] args) throws InterruptedException {
        BoundedBuffer<Integer> bb = new BoundedBuffer<>(5);

        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 10; i++) bb.put(i);
        });

        Thread t2 = new Thread(() -> {
            for (int i = 0; i < 10; i++) System.out.println("Taken: " + bb.take());
        });

        t1.start();
        t2.start();

        t1.join();
        t2.join();
    }
}

import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

public class ConcurrentBoundedBuffer<E> {
    private final Object[] buffer;
    private int head, tail;
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notEmpty = lock.newCondition();
    private final Condition notFull = lock.newCondition();

    public ConcurrentBoundedBuffer(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("Capacity must be a positive integer.");
        this.buffer = new Object[capacity];
        head = tail = -1;
    }

    public void put(E item) throws InterruptedException {
        lock.lock();
        try {
            while (isFull()) notFull.await();
            enqueue(item);
            notEmpty.signalAll();
        } finally {
            lock.unlock();
        }
    }

    public E take() throws InterruptedException {
        lock.lock();
        try {
            while (isEmpty()) notEmpty.await();
            E item = dequeue();
            notFull.signalAll();
            return item;
        } finally {
            lock.unlock();
        }
    }

    public boolean isEmpty() {
        return head == -1 || tail == -1;
    }

    public boolean IsFull() {
        return (tail + 1) % buffer.length == head;
    }

    private void enqueue(E item) {
        if (head == -1 && tail == -1) {
            buffer[++head] = item;
            tail++;
        } else {
            tail = (tail + 1) % buffer.length;
            buffer[tail] = item;
        }
    }

    private E dequeue() {
        E item = (E) buffer[head];
        if (head == tail) {
            head = -1;
            tail = -1;
        } else {
            head = (head + 1) % buffer.length;
        }
        return item;
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentBoundedBuffer<Integer> buffer = new ConcurrentBoundedBuffer<>(3);
        Thread producer = new Thread(() -> {
            for (int i = 0; i < 6; i++) {
                try {
                    buffer.put(i);
                    System.out.println("Produced: " + i);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        Thread consumer = new Thread(() -> {
            for (int i = 0; i < 6; i++) {
                try {
                    Integer item = buffer.take();
                    System.out.println("Consumed: " + item);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });
        producer.start();
        consumer.start();
        producer.join();
        consumer.join();
        System.out.println("Buffer is empty: " + buffer.isEmpty());
    }
}

