public class Cache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public Cache(BigInteger number, BigInteger... factors) {
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    public synchronized boolean addFactors(BigInteger... newFactors) {
        for (BigInteger factor : newFactors) {
            if (!Arrays.asList(this.factors).contains(factor)) {
                BigInteger[] newArray = Arrays.copyOf(this.factors, this.factors.length + 1);
                newArray[newArray.length - 1] = factor;
                this.factors = newArray;
            } else {
                return false;
            }
        }
        return true;
    }

    public synchronized BigInteger[] getFactors() {
        return Arrays.copyOf(this.factors, this.factors.length);
    }

    private static void testCache() {
        ExecutorService executor = Executors.newFixedThreadPool(3);
        BigInteger num = BigInteger.valueOf(24);
        Cache cache = new Cache(num, BigInteger.ONE, BigInteger.TWO, BigInteger.THREE, BigInteger.FOUR, BigInteger.SIX, BigInteger.EIGHT, BigInteger.TWELVE, BigInteger.TWENTY_FOUR);
        executor.submit(() -> {
            cache.addFactors(BigInteger.valueOf(3), BigInteger.valueOf(6));
        });
