import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Account {
    private int balance;

    public Account(int initialBalance) {
        this.balance = initialBalance;
    }

    public synchronized void deposit(DollarAmount amount) throws InsufficientFundsException {
        if (amount.getValue() <= 0) {
            throw new IllegalArgumentException("Deposit amount must be positive");
        }

        int newBalance = balance + amount.getValue();
        if (newBalance < 0) {
            throw new InsufficientFundsException("Insufficient funds for deposit");
        }

        balance = newBalance;
    }

    public synchronized void withdraw(DollarAmount amount) throws InsufficientFundsException {
        if (amount.getValue() <= 0) {
            throw new IllegalArgumentException("Withdrawal amount must be positive");
        }

        int newBalance = balance - amount.getValue();
        if (newBalance < 0) {
            throw new InsufficientFundsException("Insufficient funds for withdrawal");
        }

        balance = newBalance;
    }

    public synchronized int getBalance() {
        return balance;
    }

    @Override
