class ThreadSafeTransfer implements TransferLogic {
    @Override
    public void transfer(Account from, Account to, DollarAmount amount) {
        int lockOrder1 = Math.min(from.hashCode(), to.hashCode());
        int lockOrder2 = Math.max(from.hashCode(), to.hashCode());

        synchronized (lockOrder1 > lockOrder2 ? lockOrder2 : lockOrder1) {
            if (!from.equals(to)) {
                synchronized (lockOrder1 > lockOrder2 ? lockOrder1 : lockOrder2) {
                    if (amount.getValue() <= from.getBalance()) {
                        try {
