import java.util.concurrent.atomic.AtomicReference;

class Node<T> {
    final T item;
    final AtomicReference<Node<T>> next;

    Node(T item, Node<T> next) {
        this.item = item;
        this.next = new AtomicReference<>(next);
    }
}

public class TreiberStack<T> {
    private final AtomicReference<Node<T>> top;

    public TreiberStack() {
        top = new AtomicReference<>();
    }

    public boolean push(T item) {
        Node<T> node = new Node<>(item, null);
        while (true) {
            Node<T> currentTop = top.get();
            node.next.set(currentTop);
            if (top.compareAndSet(currentTop, node)) {
                return true;
            }
        }
    }

    public T pop() {
        while (true) {
            Node<T> currentTop = top.get();
            if (currentTop == null) {
                return null;
            }
            Node<T> nextTop = currentTop.next.get();
            if (top.compareAndSet(currentTop, nextTop)) {
                return currentTop.item;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        TreiberStack<Integer> stack = new TreiberStack<>();

        int threadCount = 4;
        java.util.concurrent.ExecutorService executorService = java.util.concurrent.Executors.newFixedThreadPool(threadCount);

        for (int i = 0; i < threadCount; i++) {
            executorService.submit(() -> {
                stack.push(1);
                stack.push(2);
                stack.push(3);
                stack.push(4);
                stack.push(5);

                System.out.println("Pushed 5 items");

                for (int j = 0; j < 5; j++) {
                    Integer item = stack.pop();
                    if (item != null) {
                        System.out.println("Popped " + item);
                    } else {
                        break;
                    }
                }
            });
        }

        executorService.shutdown();
        while (!executorService.isTerminated()) {
        }
        System.out.println("All tasks finished");
    }
}

