public class ConcurrentStack<T> {
    static final Node<Object> TOMBSTONE = new Node<>(null, null);
    private AtomicReference<Node<T>> top;

    ConcurrentStack() {
        top = new AtomicReference<>();
    }

    boolean push(T item) {
        while (true) {
            Node<T> currTop = top.get();
            if (currTop == TOMBSTONE) return false;
            Node<T> newNode = new Node<>(item, currTop);
            if (top.compareAndSet(currTop, newNode)) {
                return true;
            }
        }
    }

    T pop() {
        while (true) {
            Node<T> currTop = top.get();
            if (currTop == TOMBSTONE || currTop == null) return null;
            if (top.compareAndSet(currTop, currTop.next)) {
                @SuppressWarnings("unchecked")
                T item = (T) currTop.item;
                return item;
            }
        }
    }

    static class Node<T> {
        final T item;
        final Node<T> next;

        Node(T item, Node<T> next) {
            this.item = item;
            this.next = next;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack<Integer> stack = new ConcurrentStack<>();
        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(3);
        for (int i = 0; i < 10; i++) {
            executor.submit(() -> {
                for (int j = 0; j < 5; j++) stack.push(j);
            });
            executor.submit(() -> {
                for (int j = 0; j < 5; j++) System.out.println("Popped: " + stack.pop());
            });
        }
        executor.shutdown();
        executor.awaitTermination(10, java.util.concurrent.TimeUnit.SECONDS);
        System.out.println("Stack operations completed");
    }
}

import java.util.concurrent.atomic.AtomicReference;

public class TreiberStack {
    private static class Node<T> {
        final T item;
        volatile Node<T> next;

        Node(T item, Node<T> next) {
            this.item = item;
            this.next = next;
        }
    }

    private final AtomicReference<Node<?>> top = new AtomicReference<>();

    public boolean push(Object item) {
        while (true) {
            Node<?> t = top.get();
            if (t == null) {
                if (top.compareAndSet(null, new Node<>(item, null))) {
                    return true;
                }
            } else if (top.compareAndSet(t, new Node<>(item, t))) {
                return true;
            }
        }
    }

    public Object pop() {
        while (true) {
            Node<?> t = top.get();
            if (t == null) return null;
            if (top.compareAndSet(t, t.next)) {
                return t.item;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        TreiberStack stack = new TreiberStack();
        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(3);

