import java.util.*;
import java.util.concurrent.*;

class DelegatingVehicleTracker {
  private final ConcurrentHashMap<String, Point> locations;

  public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
    locations = new ConcurrentHashMap<>(initialLocations);
  }

  public Optional<Point> getLocation(String vehicleId) {
    return Optional.ofNullable(locations.get(vehicleId));
  }

  public boolean setLocation(String vehicleId, Point location) {
    return locations.computeIfPresent(vehicleId, (k, v) -> location) != null;
  }

  public Map<String, Point> getAllLocations() {
    return Collections.unmodifiableMap(locations);
  }

