            vehicleLocations.put(vehicleId, newLocation);
            return true;
        }
    }

    public Map<String, Map.Entry<Double, Double>> getAllVehicleLocations() {
        return Collections.unmodifiableMap(vehicleLocations);
    }

    public Map<String, Map.Entry<Double, Double>> getSnapshotOfVehicleLocations() {
        return vehicleLocations.entrySet().stream()
                .collect(Collectors.toUnmodifiableMap(e -> e.getKey(), Map.Entry::getValue));
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        Map<String, Map.Entry<Double, Double>> initialLocations = new HashMap<>();
        initialLocations.put("Car1", new AbstractMap.SimpleImmutableEntry<>(25.5, 30.0));
        initialLocations.put("Bike1", new AbstractMap.SimpleImmutableEntry<>(20.0, 35.5));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

        ExecutorService executor = Executors.newFixedThreadPool(3);
        executor.submit(() -> {
            tracker.setVehicleLocation("Car1", new AbstractMap.SimpleImmutableEntry<>(30.0, 25.5));
            System.out.println("New location for Car1: " + tracker.getVehicleLocation("Car1"));
