public class ConcurrentProgram {
    private static final CountDownLatch startGate = new CountDownLatch(1);
    private static final CountDownLatch endGate = new CountDownLatch(2);

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(() -> timeTasks(1, () -> System.out.println("Task 1")));
        executor.submit(() -> timeTasks(2, () -> System.out.println("Task 2")));
        startGate.countDown();
        endGate.await();
        System.out.println("All tasks completed");
        executor.shutdown();
    }

    private static void timeTasks(int threadCount, Runnable task) throws InterruptedException {
        Thread[] threads = new Thread[threadCount];
        for (int i = 0; i < threadCount; i++) {
            threads[i] = new Thread(() -> {
                try {
                    startGate.await();
                    task.run();
                    endGate.countDown();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
        }
        for (Thread thread : threads) {
            thread.start();
        }
    }
}

