import java.util.*;
import java.util.concurrent.Semaphore;

public class BoundedHashSet<T> {
    private final Set<T> set = Collections.synchronizedSet(new HashSet<>());
    private final Semaphore semaphore;

    public BoundedHashSet(int bound) {
        this.semaphore = new Semaphore(bound);
    }

    public boolean add(T o) {
        try {
            semaphore.acquire(); // Acquire a permit to add an element
            return set.add(o); // Add the element if successful
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        } finally {
            semaphore.release(); // Release the permit, whether added successfully or not
        }
    }

    public boolean remove(Object o) {
        set.remove(o); // Remove the element from set first, then release the permit
        semaphore.release();
        return true; // Return true since we always remove an existing item
    }

    public static void main(String[] args) {
        BoundedHashSet<Integer> boundedSet = new BoundedHashSet<>(3);

        // Create a Runnable to add elements concurrently
        Runnable addElementTask = () -> {
            for (int i = 0; i < 5; i++) { // Add up to bound
                if (!boundedSet.add(i)) {
                    System.out.println("Failed to add " + i);
                } else {
                    System.out.println("Added " + i);
                }
            }
        };

        // Create a Runnable to remove elements concurrently
        Runnable removeElementTask = () -> {
            for (int i = 0; i < 5; i++) { // Remove up to bound
                if (!boundedSet.remove(i)) {
                    System.out.println("Failed to remove " + i);
                } else {
                    System.out.println("Removed " + i);
                }
            }
        };

        // Execute the tasks concurrently using a thread pool with at most 4 additional threads
        ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(5, r -> {
            Thread t = new Thread(r);
            t.setDaemon(true); // Make it a daemon thread to automatically terminate when all non-daemon threads finish
            return t;
        });

        executor.execute(addElementTask);
        executor.execute(removeElementTask);
        executor.shutdown(); // Shut down the executor once tasks are submitted

        // Wait for all tasks to complete before exiting the main thread
        try {
            if (!executor.awaitTermination(10, TimeUnit.SECONDS)) {
                executor.shutdownNow(); // Force shutdown if tasks do not terminate within 10 seconds
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("BoundedSet size: " + boundedSet.set.size());
    }
}

