            }
        }

        private boolean isPrime(int n) {
            for (int i = 2; i * i <= n; i++) {
                if (n % i == 0) {
                    return false;
                }
            }
            return true;
        }
    }

    static class PrimeConsumer extends Thread {
        @Override
        public void run() {
            while (!Thread.currentThread().isInterrupted()) {
