    }
}

import java.util.concurrent.*;

public class PrimeProducerConsumer {

    static final int PRIME_COUNT = 10; // Number of primes to generate and consume

    private static BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(10);

    public static void main(String[] args) throws InterruptedException, ExecutionException {

        // Create producer thread
        PrimeProducer primeProducer = new PrimeProducer();
        primeProducer.start();

        // Create consumer thread
        Thread consumer = new Thread(() -> {
            while (!queue.isEmpty()) {
                try {
                    int number = queue.take();
                    System.out.println(number);
                } catch (InterruptedException e) {
                    break;
                }
            }
        });

        consumer.start();

        // Wait for consumer to finish processing
        consumer.join();

        // Interrupt producer thread and wait for it to finish
        primeProducer.interrupt();
        primeProducer.join();
    }

    static class PrimeProducer extends Thread {
        @Override
        public void run() {
            for (int i = 0; i < PRIME_COUNT; i++) {
                if (Thread.currentThread().isInterrupted()) break; // Check for interruption
                queue.offer(generatePrime());
            }
        }

        private int generatePrime() {
            int num = 2 + (int) Math.random() % 20; // Generate a prime number between 2 and 22
            while (!isPrime(num)) {
                num++; // Find next prime number
            }
            return num;
        }

        private boolean isPrime(int number) {
            for (int i = 2; i <= Math.sqrt(number); i++) {
                if (number % i == 0) return false;
            }
            return true;
        }
    }
}

