import java.util.*;
import java.util.concurrent.*;

public class ConcurrentExample {

    static interface Element<T> {
        void process(T data);
    }

    static interface Node<T> {
        Element<? super T> getElement();
        List<Node<T>> getChildren();
    }

    // Sequential processing method
    public static <T> void sequentialProcessing(List<T> list, Element<T> element) {
        for (T data : list) {
            element.process(data);
        }
    }

    // Parallel processing method using an ExecutorService
    public static <T> List<Future<?>> parallelProcessing(List<T> list, Element<T> element, ExecutorService executor) {
        List<Future<?>> futures = new ArrayList<>();
        for (T data : list) {
            futures.add(executor.submit(() -> element.process(data)));
        }
        return futures;
    }

    // Recursive sequential processing method for tree structure traversal
    public static <T> void recursiveSequentialProcessing(Node<T> node, Element<T> element) {
        element.process(node.getElement().data);
        for (Node<T> child : node.getChildren()) {
            recursiveSequentialProcessing(child, element);
        }
    }

    // Recursive parallel processing method for tree structure traversal using an ExecutorService
    public static <T> List<Future<?>> recursiveParallelProcessing(Node<T> node, Element<T> element, ExecutorService executor) {
        List<Future<?>> futures = new ArrayList<>();
        futures.add(executor.submit(() -> element.process(node.getElement().data)));
        for (Node<T> child : node.getChildren()) {
            futures.addAll(recursiveParallelProcessing(child, element, executor));
        }
        return futures;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Integer> list = Arrays.asList(1, 2, 3, 4, 5);
        Element<Integer> element = i -> System.out.println("Processing: " + i);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<?>> futures = parallelProcessing(list, element, executor);
        for (Future<?> future : futures) {
            future.get(); // Wait for all tasks to complete
        }

        Node<Integer> root = new Node<>() {
            @Override
            public Element<? super Integer> getElement() {
                return element;
            }

            @Override
            public List<Node<Integer>> getChildren() {
                List<Node<Integer>> children = new ArrayList<>();
                children.add(new Node<>() {
                    @Override
                    public Element<? super Integer> getElement() {
                        return element;
                    }

                    @Override
                    public List<Node<Integer>> getChildren() {
                        return Collections.emptyList();
                    }
                });
                children.add(new Node<>() {
                    @Override
                    public Element<? super Integer> getElement() {
                        return element;
                    }

                    @Override
                    public List<Node<Integer>> getChildren() {
                        List<Node<Integer>> grandChildren = new ArrayList<>();
                        grandChildren.add(new Node<>() {
                            @Override
                            public Element<? super Integer> getElement() {
                                return element;
                            }

                            @Override
                            public List<Node<Integer>> getChildren() {
                                return Collections.emptyList();
                            }
                        });
                        grandChildren.add(new Node<>() {
                            @Override
                            public Element<? super Integer> getElement() {
                                return element;
                            }

                            @Override
                            public List<Node<Integer>> getChildren() {
                                return Collections.emptyList();
                            }
                        });
                        return grandChildren;
                    }
                });
                return children;
            }
        };

        futures = recursiveParallelProcessing(root, element, executor);
        for (Future<?> future : futures) {
            future.get(); // Wait for all tasks to complete
        }

        executor.shutdown(); // Shut down the executor service after use
    }
}

