    private static <T> T sequential(Element<T> element) {
        return element.process();
    }

    private static <T> Future<T> parallel(ExecutorService executor, Element<T> element) {
        return executor.submit(element::process);
    }

    private static <T> T sequentialTree(Node<T> node) {
        List<Future<T>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildNodes()) {
            futures.add(sequentialTree(child));
        }
        return node.computeResult();
    }

    private static <T> T parallelTree(ExecutorService executor, Node<T> node) throws InterruptedException, ExecutionException {
        List<Future<T>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildNodes()) {
            futures.add(parallel(executor, () -> sequentialTree(child)));
        }
        return node.computeResult();
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        // Example usage of sequential and parallel processing
        Element<Integer> element1 = () -> 5;
        Future<Integer> futureResult1 = parallel(executor, element1);
        System.out.println("Sequential result: " + sequential(element1));
        System.out.println("Parallel result: " + futureResult1.get());

        // Example usage of sequential and parallel tree processing
        Node<Integer> node = new Node<>() {
            @Override
            public List<Node<Integer>> getChildNodes() {
                List<Node<Integer>> children = new ArrayList<>();
                children.add(new Node<>() {
                    @Override
                    public List<Node<Integer>> getChildNodes() {
                        return Collections.emptyList();
                    }

                    @Override
                    public Integer computeResult() {
                        return 1;
                    }
                });
                children.add(new Node<>() {
                    @Override
                    public List<Node<Integer>> getChildNodes() {
                        return Collections.emptyList();
                    }

                    @Override
                    public Integer computeResult() {
                        return 2;
                    }
                });
                children.add(new Node<>() {
                    @Override
                    public List<Node<Integer>> getChildNodes() {
                        return Collections.emptyList();
                    }

                    @Override
                    public Integer computeResult() {
                        return 3;
                    }
                });
                return children;
            }

            @Override
            public Integer computeResult() {
                int sum = 0;
                for (Node<Integer> child : getChildNodes()) {
                    sum += child.computeResult();
                }
                return sum;
            }
        };
        System.out.println("Sequential tree result: " + sequentialTree(node));
        System.out.println("Parallel tree result: " + parallelTree(executor, node).get());

        // Clean up the executor service
        executor.shutdown();
    }
}

import java.util.*;
import java.util.concurrent.*;

interface Element {
    int process();
}

class Node<T extends Element> {
    private final List<Node<T>> children = new ArrayList<>();
    private final T element;

    public Node(T element) {
        this.element = element;
    }

    public void addChild(Node<T> child) {
        children.add(child);
    }

    public int compute() {
        int result = element.process();
        for (Node<T> child : children) {
            result += child.compute();
        }
        return result;
    }
}

class SequentialProcessing {
    public static List<Integer> sequential(List<? extends Element> elements, ExecutorService executor) {
        List<Integer> results = new ArrayList<>();
        for (Element e : elements) {
            results.add(e.process());
        }
        return results;
    }

    public static int sequentialNode(Node<? extends Element> node, ExecutorService executor) {
        int result = node.element.process();
        for (Node<? extends Element> child : node.children) {
            result += sequentialNode(child, executor);
        }
        return result;
    }
}

class ParallelProcessing {
    public static List<Future<Integer>> parallel(List<? extends Element> elements, ExecutorService executor) throws InterruptedException, ExecutionException {
        List<Future<Integer>> results = new ArrayList<>();
        for (Element e : elements) {
            results.add(executor.submit(() -> e.process()));
        }
        return results;
    }

    public static Future<Integer> parallelNode(Node<? extends Element> node, ExecutorService executor) throws InterruptedException, ExecutionException {
        Future<Integer> result = executor.submit(() -> node.element.process());
        List<Future<Integer>> childrenResults = new ArrayList<>();
        for (Node<? extends Element> child : node.children) {
            childrenResults.add(parallelNode(child, executor));
        }
        int totalResult = result.get();
        for (Future<Integer> childResult : childrenResults) {
            totalResult += childResult.get();
        }
        return CompletableFuture.completedFuture(totalResult);
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException, ExecutionException {
        List<Integer> sequentialResults = SequentialProcessing.sequential(Arrays.asList(new Element() {
            @Override
            public int process() {
                return new Random().nextInt(4);
            }
        }, new Element() {
            @Override
            public int process() {
                return new Random().nextInt(4);
            }
        }), Executors.newFixedThreadPool(2));

        System.out.println("Sequential results: " + sequentialResults);

        Node<Element> root = new Node<>(new Element() {
            @Override
            public int process() {
                return 0; // Example
            }
        });

        root.addChild(new Node<>(new Element() {
            @Override
            public int process() {
                return 0; // Example
            }
        }));

        root.addChild(new Node<>(new Element() {
            @Override
            public int process() {
                return 0; // Example
            }
        }));

        int parallelNodeResult = ParallelProcessing.parallelNode(root, Executors.newFixedThreadPool(2)).get();
        System.out.println("Parallel node result: " + parallelNodeResult);

        List<Future<Integer>> parallelResults = ParallelProcessing.parallel(Arrays.asList(new Element() {
            @Override
            public int process() {
                return new Random().nextInt(4);
            }
        }, new Element() {
            @Override
            public int process() {
                return new Random().nextInt(4);
            }
        }), Executors.newFixedThreadPool(2));

        System.out.println("Parallel results: " + parallelResults.stream().map(Future::get).collect(Collectors.toList()));
    }
}

