import java.util.*;
import java.util.concurrent.*;

public abstract class LLMC {

void processSequentially(List<Element> elements) {
for (Element e : elements)
process(e);
}

void processInParallel(Executor exec, List<Element> elements) {
CountDownLatch latch = new CountDownLatch(elements.size());
for (final Element e : elements) {
exec.execute(() -> {
process(e);
latch.countDown();
});
}
try {
latch.await();
} catch (InterruptedException ie) {
Thread.currentThread().interrupt();
}
}

public abstract void process(Element e);

public <T> void sequentialRecursive(List<Node<T>> nodes, Collection<T> results) {
for (Node<T> n : nodes) {
results.add(n.compute());
sequentialRecursive(n.getChildren(), results);
}
}

public <T> Collection<T> parallelRecursive(List<Node<T>> nodes) throws InterruptedException {
Collection<T> results = Collections.synchronizedList(new ArrayList<>());
CountDownLatch latch = new CountDownLatch(nodes.size());

Thread worker = new Thread(() -> {
for (Node<T> n : nodes) {
T result = n.compute();
results.add(result);
sequentialRecursive(n.getChildren(), results);
latch.countDown();
}
});

worker.start();
latch.await();

return results;
}

interface Element {}
interface Node<T> { T compute(); List<Node<T>> getChildren(); }

static class MyElement implements Element {
private final String name;
public MyElement(String name) { this.name = name; }
public String toString() { return "Element: " + name; }
}

static class MyNode implements Node<String> {
private final String name;
private final List<Node<String>> children;
public MyNode(String name, List<Node<String>> children) {
this.name = name;
this.children = children != null ? children : Collections.emptyList();
}
public String compute() {
return name;
}
public List<Node<String>> getChildren() { return children; }
}

public static void main(String[] args) throws InterruptedException {
LLMC instance = new LLMC() {
public void process(Element e) {
// Minimal processing
}
};

List<Element> elements = Arrays.asList(new MyElement("A"));

instance.processSequentially(elements);

Thread executor = new Thread(() -> {
instance.processInParallel(Runnable::run, elements);
});
executor.start();
executor.join();

Node<String> leaf = new MyNode("Leaf", null);
Node<String> root = new MyNode("Root", Arrays.asList(leaf));
List<Node<String>> tree = Arrays.asList(root);

Collection<String> sequentialResults = new ArrayList<>();
instance.sequentialRecursive(tree, sequentialResults);

Collection<String> parallelResults = instance.parallelRecursive(tree);
System.out.println(parallelResults);
}
}

